<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CBC Report Card — {{ $student->name }}</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef2f6;color:#172438;font-family:Arial,Helvetica,sans-serif}.sheet{width:min(900px,96%);margin:24px auto;background:#fff;padding:34px;box-shadow:0 10px 35px rgba(20,40,70,.12)}.school{text-align:center;border-bottom:3px solid #173f73;padding-bottom:16px}.school h1{margin:0;font-size:26px;text-transform:uppercase;letter-spacing:.04em}.school p{margin:4px 0;color:#66758a;font-size:12px}.title{margin:18px 0;text-align:center}.title h2{margin:0;font-size:20px}.title span{color:#66758a;font-size:12px}.identity{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:18px}.identity div{background:#f5f8fc;border:1px solid #dfe6ef;padding:10px}.identity small{display:block;text-transform:uppercase;color:#718096;font-size:8px;font-weight:bold}.identity strong{display:block;margin-top:3px;font-size:12px}.table{width:100%;border-collapse:collapse}.table th,.table td{border:1px solid #d7dee8;padding:9px;font-size:11px}.table th{background:#173f73;color:#fff;text-align:left}.level{font-weight:bold;text-align:center;background:#edf4ff;color:#1359b5}.missed{background:#fff1f1;color:#a3212c;font-weight:bold;text-align:center}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:18px 0}.summary div{border:1px solid #dfe6ef;padding:11px;text-align:center}.summary b{display:block;font-size:18px}.summary span{font-size:9px;color:#718096}.note{padding:12px;background:#f7f9fc;border-left:4px solid #173f73;font-size:10px;color:#536277}.signatures{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;margin-top:55px}.signature{border-top:1px solid #697789;padding-top:7px;text-align:center;font-size:10px}.actions{text-align:center;margin:15px}.actions button{padding:10px 15px;border:0;background:#173f73;color:#fff;border-radius:8px;cursor:pointer}@media print{body{background:#fff}.sheet{width:100%;margin:0;box-shadow:none;padding:15mm}.actions{display:none}}@media(max-width:650px){.sheet{padding:18px}.identity,.summary{grid-template-columns:repeat(2,1fr)}.signatures{grid-template-columns:1fr}}
</style></head><body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div><main class="sheet"><header class="school"><h1>{{ $schoolName }}</h1><p>Competency Based Assessment • Learner Progress Report</p></header><div class="title"><h2>COMPETENCY BASED CURRICULUM REPORT CARD</h2><span>{{ $exam->name }} · {{ $exam->term }} · {{ $exam->academic_year }}</span></div><section class="identity"><div><small>Learner</small><strong>{{ $student->name }}</strong></div><div><small>Admission No.</small><strong>{{ $student->admission_number }}</strong></div><div><small>Grade / Class</small><strong>{{ $student->class_label ?: $student->class_name ?: '—' }}{{ $student->class_stream ? ' - '.$student->class_stream : '' }}</strong></div><div><small>Assessment status</small><strong>{{ $complete ? 'Complete' : 'Incomplete' }}</strong></div></section><table class="table"><thead><tr><th>Learning Area</th><th>Score</th><th>Achievement Level</th><th>Points</th><th>Teacher / Assessor Remark</th></tr></thead><tbody>@foreach($results as $result)<tr><td><strong>{{ $result->subject_name }}</strong>@if($result->subject_code)<br><small>{{ $result->subject_code }}</small>@endif</td><td>{{ $result->marks===null?'—':number_format((float)$result->marks,2) }}</td><td class="{{ $result->assessment_status==='missed'?'missed':'level' }}">{{ $result->assessment_status==='missed'?'MISSED':$result->achievement_level }}</td><td>{{ $result->achievement_points ?: '—' }}</td><td>{{ $result->remarks ?: $result->display_remark }}</td></tr>@endforeach</tbody></table><section class="summary"><div><b>{{ $results->count() }}</b><span>Learning areas recorded</span></div><div><b>{{ $results->where('assessment_status','missed')->count() }}</b><span>Missed assessments</span></div><div><b>{{ $points ?: '—' }}</b><span>Achievement points</span></div><div><b>{{ $average !== null ? number_format($average,1).'%' : '—' }}</b><span>Average score</span></div></section><div class="note"><strong>Achievement levels:</strong> EE = Exceeding Expectation, ME = Meeting Expectation, AE = Approaching Expectation, BE = Below Expectation. The eight actual performance levels are EE1, EE2, ME1, ME2, AE1, AE2, BE1 and BE2. Missed assessments are explicitly reported and are not treated as zero marks.</div><div class="note" style="margin-top:10px"><strong>Attendance:</strong> Present {{ $attendance['present'] ?? 0 }} · Absent {{ $attendance['absent'] ?? 0 }} · Late {{ $attendance['late'] ?? 0 }} · Excused {{ $attendance['excused'] ?? 0 }}. @if($parent)Parent / Guardian: {{ $parent->name }}@endif</div><div class="signatures"><div class="signature">Class Teacher / Assessor</div><div class="signature">Parent / Guardian</div><div class="signature">Head of Institution</div></div></main></body></html>
